import { Buffer } from 'buffer';

/**
 * A challenge is bound to one pairing, a short validity window and a random
 * nonce. The nonce must be generated by a trusted local source of randomness.
 * This module does not generate or exchange secrets.
 */
export type PairingChallenge = {
  version: 1;
  pairingId: string;
  nonce: string;
  createdAt: number;
  expiresAt: number;
};

const PAIRING_ID = /^[A-Za-z0-9_-]{16,128}$/;
const BASE64_32 = /^[A-Za-z0-9+/]{43}=$/;

export function validatePairingChallenge(value: unknown, now: number): value is PairingChallenge {
  if (!value || typeof value !== 'object' || Array.isArray(value) ||
      !Number.isSafeInteger(now)) return false;
  const record = value as Record<string, unknown>;
  if (record.version !== 1 || typeof record.pairingId !== 'string' ||
      !PAIRING_ID.test(record.pairingId) || typeof record.nonce !== 'string' ||
      !BASE64_32.test(record.nonce) ||
      Buffer.from(record.nonce, 'base64').length !== 32 ||
      typeof record.createdAt !== 'number' || !Number.isSafeInteger(record.createdAt) ||
      typeof record.expiresAt !== 'number' || !Number.isSafeInteger(record.expiresAt)) return false;
  return record.createdAt <= now && record.expiresAt > now &&
    record.expiresAt > record.createdAt &&
    record.expiresAt - record.createdAt <= 5 * 60 * 1000;
}

/** Fixed-order domain-separated bytes for HMAC proof of key possession. */
export function canonicalPairingChallenge(challenge: PairingChallenge): string {
  return JSON.stringify(['dualmind-pairing-proof-v1', challenge.version,
    challenge.pairingId, challenge.nonce, challenge.createdAt, challenge.expiresAt]);
}

/**
 * Verify possession using a trusted key already provisioned through a
 * separate authenticated channel. A successful proof alone never grants
 * permissions, persists a grant, or enables command dispatch.
 */
export async function verifyPairingProof(
  challenge: PairingChallenge,
  signature: string,
  expectedPairingId: string,
  now: number,
  verify: (message: string, signature: string, pairingId: string) => Promise<boolean>,
): Promise<boolean> {
  if (!validatePairingChallenge(challenge, now) ||
      challenge.pairingId !== expectedPairingId ||
      typeof signature !== 'string' || !BASE64_32.test(signature)) return false;
  try {
    return await verify(canonicalPairingChallenge(challenge), signature, expectedPairingId) === true;
  } catch {
    return false;
  }
}
